#!/usr/bin/env python3
"""Emit absolute Linux SNMP socket-error counters for one network namespace."""
import json
import os
import time
from pathlib import Path

COLLECTOR = "linux_snmp_socket_counters_v1"


def emit(status, **fields):
    event = {
        "event_version": 1,
        "collector": COLLECTOR,
        "collector_status": status,
        "observed_at_epoch": int(time.time()),
    }
    event.update(fields)
    print(json.dumps(event, separators=(",", ":"), sort_keys=True), flush=True)


def read_paired_table(path):
    lines = [line.split() for line in Path(path).read_text(encoding="ascii").splitlines() if line.strip()]
    if len(lines) % 2:
        raise ValueError("unpaired_proc_table")
    values = {}
    for offset in range(0, len(lines), 2):
        header, row = lines[offset], lines[offset + 1]
        if not header or not row or header[0] != row[0] or len(header) != len(row):
            raise ValueError("invalid_proc_table")
        section = header[0].rstrip(":")
        for key, value in zip(header[1:], row[1:]):
            values[f"{section}.{key}"] = int(value)
    return values


def read_snmp6(path):
    values = {}
    for line in Path(path).read_text(encoding="ascii").splitlines():
        parts = line.split()
        if len(parts) != 2:
            raise ValueError("invalid_snmp6_row")
        values[parts[0]] = int(parts[1])
    return values


try:
    boot_id = Path("/proc/sys/kernel/random/boot_id").read_text(encoding="ascii").strip()
    namespace_inode = os.stat("/proc/self/ns/net").st_ino
    netstat = read_paired_table("/proc/net/netstat")
    snmp = read_paired_table("/proc/net/snmp")
    try:
        snmp6 = read_snmp6("/proc/net/snmp6")
        ipv6_available = 1
    except FileNotFoundError:
        snmp6 = {}
        ipv6_available = 0

    names = {
        "tcp_listen_overflows_total": netstat.get("TcpExt.ListenOverflows"),
        "tcp_listen_drops_total": netstat.get("TcpExt.ListenDrops"),
        "udp4_rcvbuf_errors_total": snmp.get("Udp.RcvbufErrors"),
        "udp4_sndbuf_errors_total": snmp.get("Udp.SndbufErrors"),
        "udp6_rcvbuf_errors_total": snmp6.get("Udp6RcvbufErrors", 0),
        "udp6_sndbuf_errors_total": snmp6.get("Udp6SndbufErrors", 0),
    }
    missing = sorted(name for name, value in names.items() if value is None)
    if not boot_id or namespace_inode <= 0 or missing or any(value < 0 for value in names.values() if value is not None):
        emit(
            "contract_incomplete",
            boot_id=boot_id or None,
            network_namespace_inode=namespace_inode,
            ipv6_counters_available=ipv6_available,
            missing_fields=missing,
        )
    else:
        emit(
            "ok",
            boot_id=boot_id,
            network_namespace_inode=namespace_inode,
            ipv6_counters_available=ipv6_available,
            **names,
        )
except (OSError, UnicodeError, ValueError) as error:
    emit("read_error", error_type=type(error).__name__)
